// Generated data (P3-04 D2, D3, rulings 2 and 3). countries.json and
// time-zones.json are generated by committed scripts from committed
// snapshots whose SHA-256 is recorded in data/source/source.json. A fresh run
// of each script must give a byte-identical file, so a hand edit to a
// snapshot, a generated file or source.json fails here.
import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import path from "node:path";
import { describe, expect, it } from "vitest";
import {
  countriesJson,
  extractTzLines,
  timeZonesJson,
} from "../scripts/data-lib.mjs";
import type { CountrySource, TzSource } from "../scripts/data-lib.mjs";
import { TIME_ZONES, canonicalTimeZone } from "../src/time-zone.ts";

const pkgDir = path.join(import.meta.dirname, "..");
const read = (rel: string) => readFileSync(path.join(pkgDir, rel), "utf8");
const sha256 = (text: string) =>
  createHash("sha256").update(text, "utf8").digest("hex");

interface Source {
  countries: CountrySource;
  tzdb: TzSource;
}
const source = JSON.parse(read("data/source/source.json")) as Source;

describe("countries.json", () => {
  it("the snapshot matches its recorded SHA-256", () => {
    expect(sha256(read(`data/source/${source.countries.file}`))).toBe(
      source.countries.sha256,
    );
    expect(source.countries.commit).toBe(
      "d214094e09e52f07ba5e0573ca445c50b5a651b5",
    );
  });

  it("is byte-identical to a fresh run of the script (ruling 2)", () => {
    const fresh = execFileSync(
      process.execPath,
      ["scripts/gen-countries.mjs", "--stdout"],
      { cwd: pkgDir },
    );
    expect(
      Buffer.compare(
        fresh,
        readFileSync(path.join(pkgDir, "data/countries.json")),
      ),
    ).toBe(0);
  });

  it("the transform in-process gives the same bytes", () => {
    expect(
      countriesJson(
        read(`data/source/${source.countries.file}`),
        source.countries,
      ),
    ).toBe(read("data/countries.json"));
  });

  it("the transform rejects a malformed row, a lowercase code and a duplicate", () => {
    const head = "Name,Code\n";
    expect(() =>
      countriesJson(`${head}Atlantis,at\n`, source.countries),
    ).toThrow();
    expect(() =>
      countriesJson(`${head}A,AA,extra\n`, source.countries),
    ).toThrow();
    expect(() =>
      countriesJson(`${head}A,AB\nB,AB\n`, source.countries),
    ).toThrow();
  });
});

describe("time-zones.json", () => {
  it("the snapshot matches its recorded SHA-256, tzdb 2026e", () => {
    expect(source.tzdb.release).toBe("2026e");
    expect(source.tzdb.commit).toBe("039ef27cc5f062a2055cb67435d6d71adbefd27d");
    expect(sha256(read(`data/source/${source.tzdb.snapshot}`))).toBe(
      source.tzdb.snapshotSha256,
    );
    expect(Object.keys(source.tzdb.files)).toEqual([
      "africa",
      "antarctica",
      "asia",
      "australasia",
      "europe",
      "northamerica",
      "southamerica",
      "etcetera",
      "backward",
    ]);
  });

  it("is byte-identical to a fresh run of the script", () => {
    const fresh = execFileSync(
      process.execPath,
      ["scripts/gen-time-zones.mjs", "--stdout"],
      { cwd: pkgDir },
    );
    expect(
      Buffer.compare(
        fresh,
        readFileSync(path.join(pkgDir, "data/time-zones.json")),
      ),
    ).toBe(0);
  });

  it("extractTzLines keeps Zone and Link names only, comments and rules dropped", () => {
    const text = [
      "# comment Zone Fake/Zone",
      "Rule\tUS\t1967\tmax\t-\tNov\tSun>=1\t2:00\t0\tS",
      "Zone\tAmerica/New_York\t-4:56:02 -\tLMT\t1883 Nov 18 17:00u",
      "\t\t\t-5:00\tUS\tE%sT",
      "Link\tAsia/Kolkata\t\tAsia/Calcutta\t#= Asia/Calcutta",
      "",
    ].join("\n");
    expect(extractTzLines([{ name: "x", text }])).toBe(
      "x\tZone\tAmerica/New_York\nx\tLink\tAsia/Kolkata\tAsia/Calcutta\n",
    );
  });

  // Ruling 3a: link chains resolve transitively. tzdb 2026e has no
  // two-hop link (asserted below), so a fixture proves the resolution.
  it("resolves a two-hop (three-hop) link chain to the zone (fixture)", () => {
    const json = JSON.parse(
      timeZonesJson(read("test/fixtures/tz/two-hop.tsv"), source.tzdb),
    ) as { zones: string[]; links: Record<string, string> };
    expect(json.zones).toEqual(["Region/Real"]);
    expect(json.links).toEqual({
      "Region/Old": "Region/Real",
      "Region/Older": "Region/Real",
      "Region/Oldest": "Region/Real",
    });
  });

  it.each(["cycle", "dangling", "duplicate", "link-is-zone"])(
    "the transform rejects a %s fixture",
    (name) => {
      expect(() =>
        timeZonesJson(read(`test/fixtures/tz/${name}.tsv`), source.tzdb),
      ).toThrow();
    },
  );

  it("records that 2026e itself has no link pointing at a link", () => {
    const lines = read(`data/source/${source.tzdb.snapshot}`).split("\n");
    const linkNames = new Set(
      lines
        .filter((l) => l.split("\t")[1] === "Link")
        .map((l) => l.split("\t")[3]),
    );
    const targets = lines
      .filter((l) => l.split("\t")[1] === "Link")
      .map((l) => l.split("\t")[2]);
    expect(targets.filter((t) => linkNames.has(t))).toEqual([]);
  });

  // Independent oracle: re-derive the canonical map from the raw snapshot
  // lines by repeated substitution, without the generator's code.
  it("matches an independent re-derivation from the snapshot", () => {
    const rows = read(`data/source/${source.tzdb.snapshot}`)
      .split("\n")
      .filter((l) => l !== "")
      .map((l) => l.split("\t"));
    const zones = rows.filter((r) => r[1] === "Zone").map((r) => r[2] ?? "");
    const map = new Map<string, string>();
    for (const r of rows) if (r[1] === "Link") map.set(r[3] ?? "", r[2] ?? "");
    for (let round = 0; round < 10; round += 1) {
      for (const [name, target] of map) {
        const next = map.get(target);
        if (next !== undefined) map.set(name, next);
      }
    }
    expect([...TIME_ZONES]).toEqual([...zones].sort());
    for (const zone of zones) expect(canonicalTimeZone(zone)).toBe(zone);
    for (const [name, target] of map) {
      expect(canonicalTimeZone(name)).toBe(target);
    }
    expect(map.size).toBe(253);
  });

  // Ruling 3b: every canonical zone works with Intl.DateTimeFormat on this
  // Node, so tzdb running ahead of ICU is visible instead of silent. Any
  // exception must be listed here by name.
  it("Intl.DateTimeFormat (Node's ICU) accepts every canonical zone", () => {
    const EXCEPTIONS: readonly string[] = [];
    const rejected = TIME_ZONES.filter((zone) => {
      try {
        new Intl.DateTimeFormat("en", { timeZone: zone });
        return false;
      } catch {
        return true;
      }
    });
    expect(rejected).toEqual(EXCEPTIONS);
    expect(process.versions.node.split(".")[0]).toBe("24");
  });
});
